<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('GET');$user=require_permission('MOVIMIENTO_VER');$id=(int)($_GET['id']??0);if($id<=0)json_response(['ok'=>false,'error'=>'Movimiento inválido'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT pm.*,d.nombre departamento,s.nombre subitem,CONCAT_WS(' ',us.nombre,us.apellido_paterno,us.apellido_materno) solicitado_por,CONCAT_WS(' ',uo.nombre,uo.apellido_paterno,uo.apellido_materno) otorgado_a,CONCAT_WS(' ',ur.nombre,ur.apellido_paterno,ur.apellido_materno) registrado_por FROM presupuesto_movimiento pm JOIN departamento d ON d.departamento_id=pm.departamento_id LEFT JOIN presupuesto_subitem s ON s.subitem_id=pm.subitem_id LEFT JOIN usuario us ON us.usuario_id=pm.solicitado_por_usuario_id LEFT JOIN usuario uo ON uo.usuario_id=pm.otorgado_a_usuario_id JOIN usuario ur ON ur.usuario_id=pm.registrado_por_usuario_id WHERE pm.movimiento_id=? LIMIT 1");$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row){$db->close();json_response(['ok'=>false,'error'=>'Movimiento no encontrado'],404);}if(!movement_is_visible($db,$user,$row)){$db->close();json_response(['ok'=>false,'error'=>'Sin acceso a este movimiento'],403);}$files=[];$st=$db->prepare("SELECT archivo_id,nombre_original,mime_type,size_bytes,created_at FROM presupuesto_movimiento_archivo WHERE movimiento_id=? ORDER BY archivo_id");$st->bind_param('i',$id);$st->execute();$rs=$st->get_result();while($f=$rs->fetch_assoc()){$f['archivo_id']=(int)$f['archivo_id'];$f['size_bytes']=(int)$f['size_bytes'];$f['download_url']='api.php?route=movimientos/file&id='.$f['archivo_id'];$files[]=$f;}$st->close();$row['movimiento_id']=(int)$row['movimiento_id'];$row['departamento_id']=(int)$row['departamento_id'];$row['monto']=(float)$row['monto'];$row['files']=$files;$db->close();json_response(['ok'=>true,'data'=>$row]);
